import Foundation

enum PaywallVariant: String {
    case a = "variant_a"
    case b = "variant_b"
}

struct PaywallABTest {
    private static let key = "paywall_ab_variant"

    static var assignedVariant: PaywallVariant {
        if let raw = UserDefaults.standard.string(forKey: key),
           let variant = PaywallVariant(rawValue: raw) {
            return variant
        }
        // 50/50 split on first access
        let variant: PaywallVariant = Bool.random() ? .a : .b
        UserDefaults.standard.set(variant.rawValue, forKey: key)
        return variant
    }
}
